-- Paŝoj al plena posedo : réponses types (« corrigé type » montré aux correcteurs), lot 5 : leçons 17 à 20.
-- Questions sur le texte et analyses de langue (17.3, 18.3, 19.3, 20.3), proverbes (18.3), dérivés de KURAĜ-, BRU-, SALT- (18.4),
-- « anatomie simplifiée » de Raymond Schwartz (18.4).
-- Rédigées d'après les textes et les réponses cochées « juste » par les correcteurs ; à relire par Emmanuelle.
-- Ne remplace pas une réponse type existante ; peut être rejoué sans risque.
SET NAMES utf8mb4;

UPDATE ekzerceroj SET respondo = 'Ĉar li pasigis la tutan nokton ĉe la teleskopo, observante, notante kaj komparante diagramojn.' WHERE id = 1646 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malgranda peco da fero, peceto de mortinta stelo, kiu falis sur la teron; ĝi servis al li kiel paperpremilo. Ĝi ne estis bela (ĝi ne havis estetikan belon), sed ĝi plaĉis al li pro profesia intereso kaj pro la mistero.' WHERE id = 1647 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ŝi listigas la novaĵojn sen ordo, kiel ili aperas en la ĵurnalo kaj en la radio: tragikaj kaj banalaj aferoj (militoj, bomboj, modo, sporto) sekvas unu la alian sen transiro, en la sama tono, ofte en mallongaj frazoj sen verbo.' WHERE id = 1648 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: murdistoj kun mankatenoj kaj generaloj kun brilaj ordenoj; la lastmodaj aktualaĵoj de Dior kaj tiuj de la laboratorioj (hidrogenbomboj); la kvaropo de belegaj knabetoj kaj la voko de la junuloj al la flago; la hundido, al kiu mil homoj proponis hejmon, kaj la radioaktiva pluvo; “la urbo estas kaptita per sturmo kaj oni portos malpli longajn jupojn ĉi-jare”.' WHERE id = 1649 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La ĥaoson kaj la troon de la informoj: la novaĵoj fluas senĉese kaj miksiĝas, ĉio ŝajnas same grava (aŭ same malgrava), kaj la aŭskultanto ne plu povas distingi nek pripensi.' WHERE id = 1650 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li estis deprimita kaj maltrankvila: li sentis naŭzon, “tordiĝantan vermonodon sub la stomako”, kaj demandis sin, kio finfine okazos.' WHERE id = 1651 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Malgranda planedo kun tero kaj maro, montoj lumantaj purpurete, glaciriveroj, tre forta lumo pro la glacio kaj neĝo, maldensa atmosfero kun malmulte da oksigeno kaj malforta gravito; la plantoj marŝis serĉante la plej varmajn lokojn.' WHERE id = 1652 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La plej inteligentaj bestoj de la planedo, kovritaj per mallonga, densega ora felo, kun la pensa aparato en la plej malsupra parto de la korpo. Ili kapablis ami, krei familiojn, arton kaj ilojn, sed ankaŭ envii kaj malami.' WHERE id = 1653 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kelkaj rjuiaoj, kiuj volis havi ĉion tuj kaj iĝi tre gravaj, eksplodigis la planedon: pro envio, malpacienco kaj malamo, kaj ĉar ili trovis substancojn por esprimi sian malamon.' WHERE id = 1654 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Persona opinio. Ekzemple: pesimisma, ĉar la historio de la rjuiaoj similas al nia kaj la homoj riskas la saman sorton per siaj bomboj; sed ankaŭ iom optimisma, ĉar la vivo ĉiam rekomencas (“aŭ daŭri…”), kiel la fenikso de la titolo.' WHERE id = 1655 AND ekzerco_id = 197 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Li estis en tre malagrabla, embarasa situacio, el kiu estas malfacile eliri, kvazaŭ li estus algluita en dika kaĉo.' WHERE id = 1685 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La sufikso -um- donas nedifinitan sencon rilatan al la radiko: “sklavumi” estas labori kiel sklavo, tre pene kaj por malmulte da mono. Ĝi estas pli pitoreska ol “labori”, ĉar ĝi bildigas la penadon kaj la humiligon.' WHERE id = 1686 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar “iom da” prezentas la sumon kiel nedifinitan kaj malgravan kvanton, kvazaŭ bagatelon; krome pundo estas ankaŭ pezunuo, do la esprimo estas iom ŝerca.' WHERE id = 1687 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĝentile: “Bonvolu silenti”, “Mi petas vin ne plu paroli pri tio”. Malĝentile: “Fermu vian faŭkon!”, “Ŝtopu vian buŝaĉon!”, “Silentu, babilaĉulo!”' WHERE id = 1688 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: Li gapis stulte kiel bovo antaŭ nova pordo. Ŝi grumblis kiel urso. Li estis aplomba kiel pavo. Ŝi lamentis kiel ploristino ĉe funebro. Ĝi staris rekta kiel kandelo.' WHERE id = 1689 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉi tie -um- donas impreson de senĉesa, konfuza kaj iom senhelpa zorgado: li estis plena de zorgoj kaj ne sciis, kion fari.' WHERE id = 1690 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: silentigi, mutigi, kvietigi, trankviligi, sufoki la bruon, ŝtopi al iu la buŝon (aŭ la faŭkon), fermi al iu la buŝon, igi silenti.' WHERE id = 1691 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: foje-foje, tre tre, longe longe, pli kaj pli, iom post iom, unu post la alia.' WHERE id = 1692 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: muĝi kiel bovo; murmuri kiel rivereto; knari kiel malnova pordo; kraki kiel sekaj branĉoj; boji kiel hundo; pepi kiel birdeto; bleki kiel kapro; zumi kiel abelo; ĝemi kiel malsanulo.' WHERE id = 1693 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Vortludo: remburi signifas plenigi per mola materialo (ŝveligi kusenon), sed ĝi sonas kiel rembursi (repagi). Benzo do “ŝveligis” la prezon, vendante la leonidon multekoste, kaj tiel bone repagigis al si la ŝuldon.' WHERE id = 1694 AND ekzerco_id = 203 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tio tute ne tuŝis min, ne efikis al mi (kiel akvo glitas de la plumoj de ansero).' WHERE id = 1695 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tio tre ĝenis kaj incitis ilin; ili ne plu povis resti trankvilaj.' WHERE id = 1696 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Esti en malfacila situacio, premata de du flankoj, sen eblo eskapi.' WHERE id = 1697 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Esti tre maltrankvila kaj embarasita, ne scii, kion fari, kiel kato, kiu ne povas resti sur varmega plato.' WHERE id = 1698 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mi ne estas stulta: mia menso estas vigla kaj ruza, oni ne facile trompas min.' WHERE id = 1699 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kiu atakas min, tiu ricevos respondon: mi scias defendi min.' WHERE id = 1700 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Mensogi senhonte kaj troige, kiel oni laŭdas mortinton en funebra parolado.' WHERE id = 1701 AND ekzerco_id = 204 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: kuraĝo, kuraĝa, kuraĝe, kuraĝi, kuraĝu, kuraĝeco, kuraĝigi, kuraĝiĝi, kuraĝulo, kuraĝema, kuraĝiga, kuraĝega, malkuraĝa, malkuraĝulo, malkuraĝigi, senkuraĝa, senkuraĝiĝi, rekuraĝiĝi, ekkuraĝi k.t.p.' WHERE id = 1712 AND ekzerco_id = 206 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: bruo, brua, brue, brui, bruu, bruado, bruaĵo, bruema, bruego, brueto, bruigi, bruigilo, bruanto, bruaĉo, senbrua, senbrue, senbruigi, malbrua, ekbrui, superbrui k.t.p.' WHERE id = 1713 AND ekzerco_id = 206 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: salto, salta, salte, salti, saltu, saltado, saltegi, salteti, saltema, saltigi, saltanto, saltulo, eksalti, ensalti, elsalti, transsalti, resalti, alsalti, desalti, forsalti k.t.p.' WHERE id = 1714 AND ekzerco_id = 206 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'haroj' WHERE id = 1716 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'okuloj' WHERE id = 1717 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'nazo' WHERE id = 1718 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'buŝo' WHERE id = 1719 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'lipoj' WHERE id = 1720 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'oreloj' WHERE id = 1721 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'dentoj' WHERE id = 1722 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'kruroj' WHERE id = 1723 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'postaĵo (aŭ: gluteoj, sidvangoj)' WHERE id = 1724 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'stomako' WHERE id = 1725 AND ekzerco_id = 208 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Kalvaj”: la senfoliaj arboj estas komparataj kun kapoj sen haroj. “Arboskeletoj”: la nudaj branĉoj kaj trunkoj similas al la ostoj de skeleto.' WHERE id = 1727 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '(a) La substantivo post “kaplevante” povas esti legata kiel ĝia objekto (“levante per la kapo grizan kajton”); (b) “hazarde” antaŭ la adjektivo povas esti legata kiel priskribo de la adjektivo (libro “hazarde fremdlingva”). Senambigue: (a) Kaplevante, vi vidos grizan kraboforman kajton. (b) Mi hazarde legis fremdlingvan libron.' WHERE id = 1728 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La aŭtoro atribuas homan senton al objektoj: la kajtoj, kiuj ŝvebas malalte sen vent-rado, ŝajnas malĝojaj kaj senkuraĝaj kiel deprimitaj homoj.' WHERE id = 1729 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: kverko, fago, betulo, abio, pino, tilio, kaŝtanarbo, pomarbo, pirarbo, ĉerizarbo, olivarbo, palmo.' WHERE id = 1730 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Ludo” estas predikativo de la objekto “ĝin” (kion mi konsideris ĝi esti?): ĝi ne estas dua objekto de la verbo, do ĝi restas en nominativo.' WHERE id = 1731 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: knabaĉoj (knab-aĉ-oj: malestimo), malsanema (mal-san-em-a: inklino), osteca (ost-ec-a: kvalito), buŝeto (buŝ-et-o: malgrandigo), surpriziĝo (surpriz-iĝ-o), implikitaj (implik-it-aj: pasiva participo), solviĝis (solv-iĝ-is), ridindaĵoj (rid-ind-aĵ-oj), malŝatindaj (mal-ŝat-ind-aj).' WHERE id = 1732 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Apogi” estas transitiva (apogi ion sur io): sen objekto la propozicio estus nekompleta. “Sin” estas la objekto kaj montras, ke la subjekto (la skeleto de la kajto) apogas sin mem, t.e. apogiĝas sur la sidilo.' WHERE id = 1733 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Alglui al ili ruĝajn paperpecojn ĵus okupis lin. (aŭ: Ĵus okupis lin la algluado de ruĝaj paperpecoj al ili.)' WHERE id = 1734 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Kun “la flugilon” oni parolus pri difinita, jam konata flugilo, kvazaŭ la papilio havus nur unu; sen artikolo temas pri unu el ĝiaj flugiloj.' WHERE id = 1735 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La dupunkto anoncas klarigon de la antaŭa vorto (rimedo): ĝi enkondukas, en kio konsistas la rimedo. Oni povus diri “tio estas”, mallongigite “t.e.”.' WHERE id = 1736 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ĉar en Esperanto la tempo de subordigita propozicio estas rilata al la tempo de la ĉefverbo: en la momento, kiam li kredis, la diro estis ankoraŭ estonta.' WHERE id = 1737 AND ekzerco_id = 210 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Tio estas la rakonta (historia) prezenco: ĝi vivigas la rakonton kaj metas la leganton en la momenton de la okazaĵoj, kvazaŭ li ĉeestus ilin.' WHERE id = 1755 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Ekzemple: “la novmalkovrita de ŝi propreco de la materio”; “fari kuraĝan, kaj eĉ — laŭ ies rimarko — ‘simple fantazian’ hipotezon”.' WHERE id = 1756 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Lavango komenciĝas malgrande kaj rapide kreskas ĝis ĝi fariĝas nehaltigebla: tiel la nuklea fiziko progresis ĉiam pli rapide post la unuaj malkovroj.' WHERE id = 1757 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'Radioaktiveco (-ec-) estas la eco, la kapablo de substanco esti radioaktiva; radioaktivado (-ad-) estas la ago, la daŭra procezo de radiado.' WHERE id = 1758 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'El kie do fontis la energio de ĉi tiuj misteraj, nevideblaj radioj, kiuj efikas sur la kliŝon kaj jonizas la aeron?' WHERE id = 1759 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'tiamaj (aŭ: samtempaj, de tiu epoko)' WHERE id = 1760 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La morto mem ne “finas” la kunlaboron kiel aganto: ĝi estas ekstera kaŭzo, kiu igas la kunlaboron finiĝi. La sufikso -ig- emfazas tiun kaŭzan rolon.' WHERE id = 1761 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = '“Kaj… kaj…” signifas, ke la du kialoj validas samtempe kaj kune; ĝi emfazas ilian sumon. Oni povas diri ankaŭ “ne nur… sed ankaŭ…”.' WHERE id = 1762 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'per eksperimentoj (aŭ: per eksperimenta metodo)' WHERE id = 1763 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';
UPDATE ekzerceroj SET respondo = 'La molekula biologio estas scienco, abstrakta afero, kiu ne povas mem “provi”; tion faras la sciencistoj. La aŭtoro atribuas al ĝi homan agon.' WHERE id = 1764 AND ekzerco_id = 215 AND COALESCE(respondo, '') = '';

-- Vérification
SELECT ekzerco_id, COUNT(*) AS demandoj, SUM(COALESCE(respondo, '') <> '') AS kun_respondo FROM ekzerceroj
  WHERE ekzerco_id IN (197, 203, 204, 206, 208, 210, 215) AND forigita = 0 GROUP BY ekzerco_id;
